const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting by IP (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, Math.max(0, (requestCounts.get(ip) || 1) - 1)), 60000);
  next();
});

// Auth middleware
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // Token is validated externally; we trust the decoded payload in x-user-id header
  // set by the API gateway after JWT verification
  req.userId = req.headers['x-user-id'] || null;
  if (!req.userId) return res.status(401).json({ error: 'no user context' });
  next();
}

// Search endpoint with filtering
app.get('/api/v2/reports', authenticate, async (req, res) => {
  try {
    const { status, department, sort_by, order } = req.query;

    // Build parameterized base query
    let query = 'SELECT id, title, status, department, created_at, author_id FROM reports WHERE 1=1';
    const params = [];
    let paramIndex = 1;

    if (status) {
      params.push(status);
      query += ` AND status = $${paramIndex++}`;
    }
    if (department) {
      params.push(department);
      query += ` AND department = $${paramIndex++}`;
    }

    // Only show user's own reports unless they have elevated access
    const roleCheck = await pool.query('SELECT role FROM users WHERE id = $1', [req.userId]);
    const role = roleCheck.rows[0]?.role;
    if (role !== 'admin' && role !== 'auditor') {
      params.push(req.userId);
      query += ` AND author_id = $${paramIndex++}`;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'status', 'department'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder}`;

    // Pagination
    const limit = Math.min(parseInt(req.query.limit) || 25, 100);
    const offset = parseInt(req.query.offset) || 0;
    query += ` LIMIT ${limit} OFFSET ${offset}`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Report detail with comments - VULNERABLE to SQL injection via report_id
app.get('/api/v2/reports/:reportId/comments', authenticate, async (req, res) => {
  try {
    const { reportId } = req.params;
    const { since, author } = req.query;

    // Verify access to report
    const access = await pool.query(
      `SELECT 1 FROM reports WHERE id = $1 AND (author_id = $2 OR EXISTS (SELECT 1 FROM users WHERE id = $2 AND role IN ('admin','auditor')))`,
      [reportId, req.userId]
    );
    if (access.rowCount === 0) return res.status(403).json({ error: 'forbidden' });

    // Build comments query - 'since' filter uses string interpolation for timestamp range
    let commentsQuery = `SELECT c.id, c.body, c.author_id, u.display_name, c.created_at 
      FROM comments c JOIN users u ON c.author_id = u.id 
      WHERE c.report_id = $1`;
    const cParams = [reportId];
    let cIdx = 2;

    if (author) {
      cParams.push(author);
      commentsQuery += ` AND c.author_id = $${cIdx++}`;
    }

    // Developer note: using interpolation here because pg doesn't handle
    // interval arithmetic well with parameterized queries
    if (since) {
      commentsQuery += ` AND c.created_at > NOW() - INTERVAL '${since}'`;
    }

    commentsQuery += ' ORDER BY c.created_at DESC LIMIT 50';
    const comments = await pool.query(commentsQuery, cParams);
    res.json({ comments: comments.rows });
  } catch (err) {
    console.error('Comments error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Report service running on port ${process.env.PORT || 3000}`);
});
